function pick(table) {
  if (!table) return ''
  const loc = getLocale()
  return table[loc] || table.en || table['zh-CN'] || ''
}

export function g(key, vars = {}) {
  let s = pick(STR[key]) || key
  for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, String(v))
  return s
}

export function fishName(id) {
  return pick(FISH_NAMES[id]) || id
}

export function traitText(id) {
  return pick(TRAIT[id]) || id
}

export function tagText(id) {
  return pick(TAG[id]) || id
}

export function lifeText(spec) {
  return g(`life_${lifeOf(spec)}`)
}

export function tankName(id) {
  const tank = tankById(id)
  return g(`tank_${tank.key}`) || tank.name
}

export function lightName(id) {
  const light = lightById(id)
  if (!light) return g('lightNone')
  return g(`light_${light.id}`) || light.id
}

export function packName(id) {
  const pack = packById(id)
  if (!pack) return id
  return g(`pack_${pack.id}`) || pack.id
}

export function rarityName(id) {
  return g(`rarity_${id}`) || id
}

export function packOddsLine(pack) {
  return RARITIES.filter((id) => (pack?.weights?.[id] || 0) > 0)
    .map((id) => `${rarityName(id)} ${formatOdds(pack.weights[id])}%`)
    .join(' · ')
}

export function formatDuration(ms) {
  const s = Math.floor(ms / 1000)
  const d = Math.floor(s / 86400)
  const h = Math.floor((s % 86400) / 3600)
  const m = Math.floor((s % 3600) / 60)
  const zh = getLocale().startsWith('zh')
  if (d > 0) return zh ? `${d} 天 ${h} 小时` : `${d}d ${h}h`
  if (h > 0) return zh ? `${h} 小时 ${m} 分钟` : `${h}h ${m}m`
  if (m > 0) return zh ? `${m} 分钟` : `${m}m`
  return zh ? '不到 1 分钟' : '<1m'
}
